/*
 * A177692  The even values of PrimePi(.), with repetition.
 * https://oeis.org/A177692
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) is the n‑th even value of PrimePi, with repetition when *
 *            the value stays even. The sequence is generated by incrementally
 *            * evaluating PrimePi(n) for consecutive integers n, and
 *            appending the * current prime count whenever it is even
 * Range:     u8 n <= 74, u16 n <= 74, u32 n <= 74, u64 n <= 74, u128 n <= 74,
 *            big any n
 * Helpers:   is_prime
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdbool.h>
#include <stddef.h>

/* External helper: tests whether an integer is prime. */
#include "../utils/is_prime.h"

/* Static cache of computed even PrimePi values. */
static seq_t *cache   = NULL;   /* allocated array of seq_t */
static size_t cache_len = 0;    /* number of values stored */
static size_t cache_cap = 0;    /* current capacity of cache */

/* Current state of the incremental computation. */
static idx_t  next_num   = 1;   /* the next integer to test for primality */
static seq_t  current_pi = 0;   /* Pi(next_num - 1), i.e. the count of primes < next_num */

/* Append a new term to the cache, expanding if necessary. */
static void cache_append(seq_t value)
{
    if (cache_cap == 0) {
        cache_cap = 64;
        cache = (seq_t *)malloc(cache_cap * sizeof(seq_t));
    } else if (cache_len == cache_cap) {
        cache_cap <<= 1;                           /* double capacity */
        cache = (seq_t *)realloc(cache, cache_cap * sizeof(seq_t));
    }
    cache[cache_len++] = value;
}

/* Main sequence function. */
seq_t a(idx_t n)
{
    if (n == 0) return 0;          /* undefined for n = 0, return 0 for safety */

    /* Generate terms until we have at least n of them. */
    while (cache_len < n) {
        /* Update PrimePi if next number is prime. */
        if (next_num >= 2 && is_prime(next_num))
            ++current_pi;

        /* If the current PrimePi value is even, record it. */
        if ((current_pi & 1) == 0)
            cache_append(current_pi);

        ++next_num;
    }

    /* Return the requested term (1‑based indexing). */
    return cache[n - 1];
}
